readmem.source:
module Top;
  logic [7:0] desc_mem [3:0];
  logic [7:0] short_mem [0:3];
  logic [7:0] long_mem [-1:2];
  initial begin
    short_mem[0]=8'h11; short_mem[1]=8'h22; short_mem[2]=8'h33; short_mem[3]=8'h44;
    long_mem[-1]=8'h11; long_mem[0]=8'h22; long_mem[1]=8'h33; long_mem[2]=8'h44;
    $readmemh("descending.hex", desc_mem, 3, 1);
    $readmemh("short.hex", short_mem, 3, 2);
    $readmemh("long.hex", long_mem, -1, 0);
    if ({desc_mem[3],desc_mem[2],desc_mem[1]} !== 24'haabbcc) $fatal(1,"descending");
    if ({short_mem[0],short_mem[1],short_mem[2],short_mem[3]} !== 32'h112233aa) $fatal(1,"short");
    if ({long_mem[-1],long_mem[0],long_mem[1],long_mem[2]} !== 32'hbbcc3344) $fatal(1,"long");
    $display("memory checks passed");
    $finish;
  end
endmodule
